import { APP_NAME, APP_NAME_A, APP_NAME_B } from "./brand.jsx";
import { display } from "../styles.jsx";

// ---------- the artwork ----------
//
// The logo, as supplied, embedded rather than linked. Two crops of the one
// file, because one image cannot do both jobs: the lockup carries the wordmark
// and the line under it and is legible from about 100px up, and the emblem on
// its own still reads at 16px in a browser tab, where the lockup turns to mush.
//
// Embedded as data rather than served as files on purpose. The sign-in screen
// is the first thing a crew sees, sometimes in a basement with no signal, and
// the native shell ships its own copy of this page — a linked file would be
// missing in both cases. It costs about 140KB on the first page load and
// nothing after it, and it is on neither poll path.
//
// To replace the artwork: regenerate these two strings from the new file.
// Nothing else in the app knows what the logo looks like.
export const BRAND_LOCKUP_SRC = "data:image/png;base64,";
export const BRAND_MARK_SRC = "data:image/png;base64,";

// The emblem on its own, for anywhere the app has to say "PulseOps" in a small
// space — the masthead, a bar, beside the name in type.
export function BrandMark({ size = 40, style }) {
  return (
    <img
      src={BRAND_MARK_SRC}
      alt=""
      aria-hidden="true"
      width={size}
      height={size}
      style={{ display: "block", flex: "none", ...style }}
    />
  );
}

// The whole logo: emblem, name and the line beneath, as drawn. Used where there
// is room for it — the sign-in and loading screens. It already contains the
// name, so nothing sets the name in type beside it.
export function BrandLockup({ size = 150 }) {
  return (
    <img
      src={BRAND_LOCKUP_SRC}
      alt={APP_NAME}
      width={size}
      height={size}
      style={{ display: "block", flex: "none" }}
    />
  );
}

// The name as it is written: PulseOps. Capital P, capital O, the rest lower
// case — not PULSEOPS. It was being run through toUpperCase and spaced out like
// a masthead, which is a different name to read and not the one on the mark.
// "Pulse" white, "Ops" red, the way the artwork sets it.
export function Wordmark({ size = 20 }) {
  return (
    <span
      style={{
        fontFamily: display,
        fontWeight: 800,
        fontSize: size,
        letterSpacing: -0.3,
        whiteSpace: "nowrap",
        lineHeight: 1,
      }}
    >
      <span style={{ color: "var(--ink)" }}>{APP_NAME_A}</span>
      <span style={{ color: "var(--brand)" }}>{APP_NAME_B}</span>
    </span>
  );
}

// The two crests are off the screen for the moment, and nothing about them has
// been thrown away to do it: the artwork below is untouched, and every place
// that ever drew one asks this flag first. Turning them back on is this one
// line going back to true — there is no other edit to make and nothing to
// re-paste.
export const SHOW_LOGOS = false;

// The organisation the board belongs to, named in one place rather than typed
// into each sheet and screen. It carries no hospital's name at the moment; put
// one here and it appears again on the printed footers, the login note and the
// crest labels at once, with nothing to go hunting for.
export const ORG_NAME = "";

// The name as it goes onto a printed footer, which reads "<org> Ambulance
// Services" — so the trailing space belongs to the name, and with no name the
// footer closes up to "Ambulance Services" rather than leaving a gap.
//
// Escaped here rather than at the point of use: one of the two report builders
// renders an empty cell as "NA", and would happily print that in place of a
// name nobody has set.
export const ORG_STAMP = ORG_NAME
  ? `${ORG_NAME.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")} `
  : "";

export const HOSPITAL_LOGO = "data:image/png;base64,";
export const DEPT_LOGO = "data:image/png;base64,";

export const POLL_MS = 3000;
// The board is not one thing read at one speed.
//
// Every open device was pulling all fifteen keys every three seconds, and four
// fifths of that was the submitted-log archive — which changes about four times
// a day. A real board measured 1.09 MB a tick: 21 MB a minute, 1.3 GB an hour,
// per device, most of it the same bytes over and over. On a crew's phone that
// is somebody's data allowance, and it grows every day the department files
// another shift.
//
// So the poll is split. Units, calls, the schedule and the chat are what change
// while somebody is watching, and they keep the three seconds. The filed logs,
// the kept days, the event feed and the checklists are read on a slower beat,
// and refreshed at once when a tab that shows them is opened — so nothing on
// screen is ever more stale than the moment it was opened.
export const COLD_POLL_MS = 30000;
// The three housekeeping passes — filing a finished shift, keeping a finished
// day, completing a submission whose last call has closed — each re-read the
// whole submitted-log archive to decide whether they have anything to do. On a
// department a fortnight in that is 861 KB an ask, and they were asking every
// thirty to sixty seconds to answer "no" almost every time.
//
// None of them is time-critical: a shift filed four minutes after its window
// closed is filed correctly. Five minutes, staggered so they do not all reach
// for the same key on the same tick.
export const HOUSEKEEPING_MS = 5 * 60 * 1000;
// How many activity lines the log sheet keeps. Every board reads the whole log
// on each poll, so this can't grow without limit — the durable record of what
// happened on a call is the call itself, which is kept forever (see
// CompletedCalls) and exported in full.
export const LOG_CAP = 400;